package com.tastenest.servlet;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import com.tastenest.util.DB;
@WebServlet("/register") public class RegisterServlet extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{res.setContentType("application/json");String name=req.getParameter("name"),mobile=req.getParameter("mobile"),email=req.getParameter("email"),pass=req.getParameter("password");try{DB.init();try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("INSERT INTO users(name,mobile,email,password,role) VALUES(?,?,?,?, 'CUSTOMER')",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,mobile);p.setString(3,email);p.setString(4,pass);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();HttpSession s=req.getSession();s.setAttribute("userId",k.getInt(1));s.setAttribute("userName",name);s.setAttribute("userEmail",email);s.setAttribute("role","CUSTOMER");}res.getWriter().print("{\"ok\":true}");}}catch(SQLIntegrityConstraintViolationException e){res.getWriter().print("{\"ok\":false,\"error\":\"Email already registered\"}");}catch(Exception e){res.setStatus(500);res.getWriter().print("{\"ok\":false,\"error\":\"Registration failed\"}");}}}
